package com.nthexperience.nota;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.net.Uri;
import android.os.Build;
import org.json.*;
import java.util.*;

/** Optional task notices, with user-controlled dismissal and no background service. */
public class TaskNotificationReceiver extends BroadcastReceiver {
 private static final String PREFS="nota-task-notices";
 static JSONArray read(Context c,String key){try{return new JSONArray(c.getSharedPreferences(PREFS,0).getString(key,"[]"));}catch(Exception e){return new JSONArray();}}
 static void write(Context c,String key,JSONArray value){c.getSharedPreferences(PREFS,0).edit().putString(key,value.toString()).commit();}
 static PendingIntent intent(Context c,String id,String action){Intent i=new Intent(c,TaskNotificationReceiver.class).setAction(action).setData(Uri.parse("nthnota://task/"+Uri.encode(id)+"/"+action)).putExtra("id",id);return PendingIntent.getBroadcast(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static boolean enabled(Context c){return (Build.VERSION.SDK_INT<33||c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED)&&c.getSystemService(NotificationManager.class).areNotificationsEnabled();}
 static JSONObject find(JSONArray a,String id){for(int k=0;k<a.length();k++){JSONObject r=a.optJSONObject(k);if(r!=null&&id.equals(r.optString("id")))return r;}return null;}
 static void cancel(Context c,String id){c.getSystemService(AlarmManager.class).cancel(intent(c,id,"deliver"));c.getSystemService(NotificationManager.class).cancel(id,2);}
 static synchronized void sync(Context c,String json){try{JSONArray incoming=new JSONArray(json);if(incoming.length()>3000)return;JSONArray old=read(c,"items"),actions=read(c,"actions"),next=new JSONArray();Set<String> ids=new HashSet<>();for(int k=0;k<incoming.length();k++){JSONObject r=incoming.getJSONObject(k);String id=r.optString("id");if(!id.matches("[A-Za-z0-9_:-]{1,201}")||!r.optString("itemId").matches("[A-Za-z0-9_-]{1,100}")||r.optLong("rev")<=0||(!r.optBoolean("ongoing")&&r.optLong("when")<=0))continue;JSONObject action=find(actions,id);if(action!=null&&action.optLong("rev")==r.optLong("rev"))continue;ids.add(id);JSONObject was=find(old,id);boolean same=was!=null&&was.optLong("rev")==r.optLong("rev")&&was.optLong("when")==r.optLong("when")&&was.optBoolean("ongoing")==r.optBoolean("ongoing")&&was.optString("title").equals(r.optString("title"))&&was.optString("body").equals(r.optString("body"));if(was!=null&&was.optLong("rev")==r.optLong("rev"))r.put("fired",was.optBoolean("fired"));next.put(r);if(!same||!r.optBoolean("fired")&&r.optLong("when")<=System.currentTimeMillis()){if(NotificationPolicy.updateInPlace(was,r,System.currentTimeMillis()))c.getSystemService(AlarmManager.class).cancel(intent(c,id,"deliver"));else cancel(c,id);if(r.optLong("when")>System.currentTimeMillis())c.getSystemService(AlarmManager.class).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,r.optLong("when"),intent(c,id,"deliver"));else if(r.optBoolean("ongoing")||!r.optBoolean("fired")){if(show(c,r))r.put("fired",true);}}}for(int k=0;k<old.length();k++){JSONObject r=old.optJSONObject(k);if(r!=null&&!ids.contains(r.optString("id")))cancel(c,r.optString("id"));}write(c,"items",next);}catch(Exception ignored){}}
 static boolean show(Context c,JSONObject r){if(!enabled(c))return false;NotificationManager nm=c.getSystemService(NotificationManager.class);String channel="nota-task-notices";NotificationChannel ch=new NotificationChannel(channel,"Task reminders",NotificationManager.IMPORTANCE_DEFAULT);ch.setDescription("Reminders and optional ongoing task cards");nm.createNotificationChannel(ch);NotificationChannel actual=nm.getNotificationChannel(channel);if(actual!=null&&actual.getImportance()==NotificationManager.IMPORTANCE_NONE)return false;String id=r.optString("id");Intent open=new Intent(c,MainActivity.class).putExtra("item_id",r.optString("itemId")).setData(Uri.parse("nthnota://open/"+Uri.encode(r.optString("itemId")))).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent click=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder builder=new Notification.Builder(c,channel).setSmallIcon(R.drawable.ic_note).setContentTitle(r.optString("title","Task reminder")).setContentText(r.optString("body")).setStyle(new Notification.BigTextStyle().bigText(r.optString("body"))).setContentIntent(click).setOnlyAlertOnce(true).setOngoing(r.optBoolean("ongoing")).setAutoCancel(!r.optBoolean("ongoing")).setVisibility(Notification.VISIBILITY_PRIVATE).setDeleteIntent(intent(c,id,"stop"));if(!"item".equals(r.optString("kind")))builder.addAction(new Notification.Action.Builder(null,"Complete",intent(c,id,"complete")).build());Notification n=builder.addAction(new Notification.Action.Builder(null,"Stop showing",intent(c,id,"stop")).build()).build();nm.notify(id,2,n);return true;}
 static synchronized void restore(Context c){JSONArray a=read(c,"items"),actions=read(c,"actions");for(int k=0;k<a.length();k++){JSONObject r=a.optJSONObject(k);if(r==null)continue;JSONObject action=find(actions,r.optString("id"));if(action!=null&&action.optLong("rev")==r.optLong("rev"))continue;if(r.optLong("when")>System.currentTimeMillis())c.getSystemService(AlarmManager.class).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,r.optLong("when"),intent(c,r.optString("id"),"deliver"));else if(r.optBoolean("ongoing")||!r.optBoolean("fired")){try{if(show(c,r))r.put("fired",true);}catch(Exception ignored){}}}write(c,"items",a);}
 @Override public void onReceive(Context c,Intent i){String id=i.getStringExtra("id");if(id==null)return;synchronized(TaskNotificationReceiver.class){JSONArray a=read(c,"items");JSONObject r=find(a,id);if(r==null)return;try{if("deliver".equals(i.getAction())){if(r.optLong("when")>System.currentTimeMillis()+1000||r.optBoolean("fired"))return;if(show(c,r))r.put("fired",true);write(c,"items",a);}else if("complete".equals(i.getAction())||"stop".equals(i.getAction())){JSONArray actions=read(c,"actions"),next=new JSONArray();for(int k=Math.max(0,actions.length()-2999);k<actions.length();k++){JSONObject x=actions.optJSONObject(k);if(x!=null&&!id.equals(x.optString("id")))next.put(x);}next.put(new JSONObject().put("id",id).put("rev",r.optLong("rev")).put("action",i.getAction()));write(c,"actions",next);cancel(c,id);}}catch(Exception ignored){}}}
}
